286	// handleHeartbeat renews heartbeat_at of one path-addressed instance. The
287	// caller does not resubmit address, port, health state or weight: only
288	// heartbeat_at is replaced and every other field keeps its current value.
289	func (s *Server) handleHeartbeat(c *gin.Context) {
290		bag, apiErr := buildParamBag(c)
291		if apiErr != nil {
292			writeError(c, apiErr)
293			return
294		}
295		serviceName, apiErr := bag.locateText("serviceName", serviceNameKeys, "service_name must not be empty")
296		if apiErr != nil {
297			writeError(c, apiErr)
298			return
299		}
300		instanceID, apiErr := bag.locateText("instanceId", instanceIDKeys, "instance_id must not be empty")
301		if apiErr != nil {
302			writeError(c, apiErr)
303			return
304		}
305		heartbeatAt, apiErr := requireHeartbeat(bag)
306		if apiErr != nil {
307			writeError(c, apiErr)
308			return
309		}
310		updated, err := s.store.TouchHeartbeats(serviceName, []store.HeartbeatTarget{
311			{InstanceID: instanceID, HeartbeatAt: heartbeatAt},
312		})
313		if apiErr := mapTargetError(err); apiErr != nil {
314			writeError(c, apiErr)
315			return
316		}
317		c.JSON(200, gin.H{"instance": instanceJSON(updated[0])})
318	}
