515	func mapTargetError(err error) *apiError {
516		switch {
517		case err == nil:
518			return nil
519		case errors.Is(err, store.ErrInstanceNotFound):
520			return errInstanceNotFound()
521		default:
522			return errStorageUnavailable()
523		}
524	}
