644		instance, found, err := s.store.GetInstance(serviceName, instanceID)
645		if err != nil {
646			return store.Instance{}, errStorageUnavailable()
647		}
648		if !found {
649			return store.Instance{}, errInstanceNotFound()
650		}
651		return instance, nil
652	}
653	
654	// handleGetInstance serves the full record query entry.
655	func (s *Server) handleGetInstance(c *gin.Context) {
