111	// dangling "}" or "]" because those are not value tokens. A second Decode
112	// must therefore return exactly io.EOF, which is true only once the object
113	// has ended and nothing but whitespace remains.
114	func readStrictObjectBody(c *gin.Context) (map[string]any, *apiError) {
115		if c.Request.Body == nil {
116			return nil, errInvalidParameter("request body must be a JSON object")
