282	// parsePortValue accepts a non-negative integer port number in the range
283	// [0, 9223372036854775807]. JSON numbers and numeric strings are parsed from
284	// their decimal text with exact integer semantics: values above 2^53 keep
285	// their exact value, fractional forms such as 8080.0 or 8.08e3 collapse to
286	// their integer value, and the int64 bound is enforced without rounding, so
287	// 9223372036854775808 is rejected instead of overflowing the conversion.
288	func parsePortValue(value any) (int64, bool) {
289		switch typed := value.(type) {
290		case json.Number:
291			return parsePortText(typed.String())
292		case string:
293			return parsePortText(strings.TrimSpace(typed))
294		case float64:
295			// A float64 at or beyond 2^63 cannot be a valid port: the largest
296			// exactly representable candidate below it is 2^63-1024, and the
297			// int64 conversion of anything larger would overflow.
298			if math.IsNaN(typed) || math.IsInf(typed, 0) || typed != math.Trunc(typed) ||
299				typed < 0 || typed >= 9223372036854775808.0 {
300				return 0, false
301			}
302			return int64(typed), true
303		case int:
304			return int64(typed), typed >= 0
305		case int64:
306			return typed, typed >= 0
307		default:
308			return 0, false
309		}
