312	// portNumberPattern is the decimal grammar a port may use: an integer or a
313	// fixed/scientific decimal with an optional sign.
314	var portNumberPattern = regexp.MustCompile(`^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)([eE][+-]?[0-9]+)?$`)
315	
316	// parsePortText parses the exact integer value of a decimal number without
317	// going through float64. The mantissa is kept as a digit string and the
318	// exponent as a small int, so huge exponents are rejected by digit counting
319	// instead of materializing enormous integers.
320	func parsePortText(text string) (int64, bool) {
321		// Fast path: a plain decimal integer, exact for the whole int64 range.
322		if number, err := strconv.ParseInt(text, 10, 64); err == nil {
323			return number, number >= 0
324		}
325		if !portNumberPattern.MatchString(text) {
326			return 0, false
327		}
328		negative := strings.HasPrefix(text, "-")
329		mantissa := strings.TrimLeft(text, "+-")
330		exponent := 0
331		if at := strings.IndexAny(mantissa, "eE"); at >= 0 {
332			expText := mantissa[at+1:]
333			mantissa = mantissa[:at]
334			if digits := strings.TrimLeft(strings.TrimLeft(expText, "+-"), "0"); len(digits) > 6 {
335				// |exponent| >= 10^6: the value is either far beyond the int64
336				// bound or far below one; only an all-zero mantissa is still
337				// exactly zero.
338				if allZeroDigits(mantissa) {
339					return 0, true
340				}
341				return 0, false
342			}
343			exponent, _ = strconv.Atoi(expText)
344		}
345		intPart, fracPart := mantissa, ""
346		if at := strings.IndexByte(mantissa, '.'); at >= 0 {
347			intPart, fracPart = mantissa[:at], mantissa[at+1:]
348		}
349		// value = digits * 10^k
350		digits := intPart + fracPart
351		k := exponent - len(fracPart)
352		digits = strings.TrimLeft(digits, "0")
353		for strings.HasSuffix(digits, "0") {
354			digits = digits[:len(digits)-1]
355			k++
356		}
357		if digits == "" {
358			return 0, true // exact zero, in any form
359		}
360		if negative || k < 0 {
361			// A negative port is out of range; a negative remaining exponent
362			// leaves a fractional part, so the value is not an integer.
363			return 0, false
364		}
365		if len(digits)+k > 19 {
366			return 0, false
367		}
368		number, err := strconv.ParseInt(digits+strings.Repeat("0", k), 10, 64)
369		if err != nil {
370			return 0, false // 19 digits but beyond math.MaxInt64
371		}
372		return number, true
373	}
374	
375	// allZeroDigits reports whether a mantissa (digits with an optional dot)
376	// denotes zero.
377	func allZeroDigits(mantissa string) bool {
378		for _, r := range mantissa {
379			if r != '0' && r != '.' {
380				return false
381			}
382		}
383		return true
384	}
