393	func toFloat(value any) (float64, bool) {
394		switch typed := value.(type) {
395		case float64:
396			return typed, true
397		case int:
398			return float64(typed), true
399		case int64:
400			return float64(typed), true
401		case json.Number:
402			number, err := typed.Float64()
403			if err != nil {
404				return 0, false
405			}
406			return number, true
407		case string:
408			number, err := strconv.ParseFloat(strings.TrimSpace(typed), 64)
409			if err != nil {
410				return 0, false
411			}
412			return number, true
413		default:
414			return 0, false
415		}
416	}
417	
418	func parseHealthValue(value any) (bool, bool) {
419		switch typed := value.(type) {
420		case bool:
421			return typed, true
422		case float64:
423			switch typed {
424			case 1:
425				return true, true
426			case 0:
427				return false, true
428			}
429		case json.Number:
430			if number, err := typed.Float64(); err == nil {
431				switch number {
432				case 1:
433					return true, true
434				case 0:
435					return false, true
436				}
437			}
438		case string:
439			switch strings.ToLower(strings.TrimSpace(typed)) {
440			case "healthy", "up", "on", "true", "1", "yes":
441				return true, true
442			case "unhealthy", "down", "off", "false", "0", "no":
443				return false, true
444			}
445		}
446		return false, false
447	}
448	
449	// Accepted timestamps cover [0000-01-01T00:00:00Z, 10000-01-01T00:00:00Z)
450	// once converted to UTC: the lower bound is included, the upper bound is
451	// excluded. These are exactly the instants the RFC3339 storage format can
452	// write and read back, so anything outside could never round-trip.
453	var (
454		minAcceptedTime = time.Date(0, 1, 1, 0, 0, 0, 0, time.UTC)
455		maxAcceptedTime = time.Date(10000, 1, 1, 0, 0, 0, 0, time.UTC)
456	)
457	
458	func inAcceptedTimeRange(t time.Time) bool {
459		t = t.UTC()
460		return !t.Before(minAcceptedTime) && t.Before(maxAcceptedTime)
461	}
462	
463	func parseTimeValue(value any) (time.Time, bool) {
464		switch typed := value.(type) {
465		case string:
466			text := strings.TrimSpace(typed)
467			if text == "" {
468				return time.Time{}, false
469			}
470			if number, err := strconv.ParseFloat(text, 64); err == nil {
471				return unixTimeInRange(number)
472			}
473			for _, layout := range []string{time.RFC3339Nano, time.RFC3339, "2006-01-02T15:04:05", "2006-01-02 15:04:05"} {
474				if parsed, err := time.Parse(layout, text); err == nil {
475					if !inAcceptedTimeRange(parsed) {
476						return time.Time{}, false
477					}
478					return parsed, true
479				}
480			}
481		case float64:
482			return unixTimeInRange(typed)
483		case json.Number:
484			number, err := typed.Float64()
485			if err != nil {
486				return time.Time{}, false
487			}
488			return unixTimeInRange(number)
489		}
490		return time.Time{}, false
