494	// accepted range. The range check runs on the float itself, before any int64
495	// conversion, so non-finite values (NaN, Inf, Infinity with any sign) and
496	// out-of-range finite values are rejected instead of overflowing and
497	// wrapping back into a valid-looking date.
498	func unixTimeInRange(seconds float64) (time.Time, bool) {
499		if math.IsNaN(seconds) || math.IsInf(seconds, 0) ||
500			seconds < float64(minAcceptedTime.Unix()) || seconds >= float64(maxAcceptedTime.Unix()) {
501			return time.Time{}, false
502		}
503		return unixTime(seconds), true
504	}
505	
506	func unixTime(seconds float64) time.Time {
507		whole := int64(seconds)
508		fraction := seconds - float64(whole)
509		return time.Unix(whole, int64(fraction*1e9)).UTC()
510	}
511	
512	// parseTimeout accepts a number of seconds or a duration string such as "30s".
513	// A non-positive duration is reported as invalid by the caller.
514	func parseTimeout(value any) (time.Duration, bool) {
515		switch typed := value.(type) {
516		case float64:
517			if math.IsNaN(typed) || math.IsInf(typed, 0) {
518				return 0, false
519			}
520			return time.Duration(typed * float64(time.Second)), true
521		case json.Number:
522			number, err := typed.Float64()
523			if err != nil || math.IsNaN(number) || math.IsInf(number, 0) {
524				return 0, false
525			}
526			return time.Duration(number * float64(time.Second)), true
527		case string:
528			text := strings.TrimSpace(typed)
529			if text == "" {
530				return 0, false
531			}
532			if duration, err := time.ParseDuration(text); err == nil {
533				return duration, true
534			}
535			if number, err := strconv.ParseFloat(text, 64); err == nil && !math.IsNaN(number) && !math.IsInf(number, 0) {
536				return time.Duration(number * float64(time.Second)), true
537			}
538		}
