1	package api
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"net/http"
7		"strings"
8		"testing"
9	)
10	
11	// Complete, otherwise-valid batch bodies. The register batch mixes an
12	// overwrite of the existing i-1 with creation of i-3; accepting any of them
13	// would either rewrite i-1 or create i-3, so a rejection leaves both visible.
14	const registerTrailerObjectByPath = `{"instances":[` +
15		`{"instance_id":"i-1","address":"10.0.0.1:9000","port":9000,"healthy":false,"weight":77,"heartbeat_at":"2026-10-01T12:30:00Z"},` +
16		`{"instance_id":"i-3","address":"10.0.0.3:9003","port":9003,"healthy":true,"weight":88,"heartbeat_at":"2026-10-01T12:31:00Z"}]}`
17	
18	const registerTrailerObjectByBody = `{"service_name":"svc","instances":[` +
19		`{"instance_id":"i-1","address":"10.0.0.1:9000","port":9000,"healthy":false,"weight":77,"heartbeat_at":"2026-10-01T12:30:00Z"},` +
20		`{"instance_id":"i-3","address":"10.0.0.3:9003","port":9003,"healthy":true,"weight":88,"heartbeat_at":"2026-10-01T12:31:00Z"}]}`
21	
22	const weightTrailerObject = `{"updates":[` +
23		`{"instance_id":"i-1","weight":55},` +
24		`{"instance_id":"i-2","weight":66}]}`
25	
26	type batchEndpoint struct {
27		name   string
28		method string
29		path   string
30		object string
31	}
32	
33	func bodyIntegrityEndpoints() []batchEndpoint {
34		return []batchEndpoint{
35			{"register-path", http.MethodPost, "/api/v1/services/svc/instances/batch", registerTrailerObjectByPath},
36			{"register-body", http.MethodPost, "/api/v1/register/batch", registerTrailerObjectByBody},
37			{"weight", http.MethodPut, "/api/v1/services/svc/instances/weight", weightTrailerObject},
38		}
39	}
40	
41	// publicInstance fetches a full record through the public GET entry. A 404
42	// reports found=false so rejected batches can be proven not to create rows.
43	func publicInstance(t *testing.T, router http.Handler, service, id string) (map[string]any, bool) {
44		t.Helper()
45		rec := doRequest(t, router, http.MethodGet,
46			fmt.Sprintf("/api/v1/services/%s/instances/%s", service, id), nil)
47		switch rec.Code {
48		case http.StatusOK:
49			return decodeBody(t, rec)["instance"].(map[string]any), true
50		case http.StatusNotFound:
51			return nil, false
52		default:
53			t.Fatalf("GET %s/%s: status %d body %s", service, id, rec.Code, rec.Body.String())
54			return nil, false
55		}
56	}
57	
58	// assertOriginalI1 verifies every field of the pre-existing svc/i-1 record
59	// through the public query, proving a rejected request performed no overwrite.
60	func assertOriginalI1(t *testing.T, inst map[string]any) {
61		t.Helper()
62		if inst["service_name"] != "svc" || inst["instance_id"] != "i-1" ||
63			inst["address"] != "10.0.0.8:8080" || inst["port"].(float64) != 8080 ||
64			inst["healthy"] != true || inst["weight"].(float64) != 10 ||
65			inst["heartbeat_at"] != baseTime {
66			t.Fatalf("svc/i-1 changed after rejected request: %v", inst)
67		}
68	}
69	
70	// TestBatchEntriesRejectDataAfterObject covers the integrity gap: a complete
71	// valid object followed immediately or after JSON whitespace by a stray "}",
72	// "]", a second object or null must be rejected on all three batch entries,
73	// and the rejection must leave no partial write behind.
74	func TestBatchEntriesRejectDataAfterObject(t *testing.T) {
75		trailers := []string{"}", "]", "{}", "null", " }", "\t]\n", " {}", " null"}
76	
77		for _, ep := range bodyIntegrityEndpoints() {
78			router, st := testRouter(t)
79			registerInstance(t, router, weightRecord())
80			second := weightRecord()
81			second["instance_id"] = "i-2"
82			second["weight"] = 3
83			registerInstance(t, router, second)
84			other := weightRecord()
85			other["service_name"] = "other"
86			registerInstance(t, router, other)
87	
88			for _, trailer := range trailers {
89				t.Run(ep.name+"+"+fmt.Sprintf("%q", trailer), func(t *testing.T) {
90					rec := doRawRequest(t, router, ep.method, ep.path, ep.object+trailer)
