		"/api/v1/services/svc/instances/i-1/heartbeat",
		map[string]any{"heartbeat_at": 1759324800})
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d body %s", rec.Code, rec.Body.String())
	}

