	"net/http"
	"testing"
)

func TestReportedBugsFixed(t *testing.T) {
	router, _ := testRouter(t)
	registerInstance(t, router, weightRecord())

	// {"weight":5}] accepted before fix
	rec := doRawRequest(t, router, http.MethodPut,
		"/api/v1/services/svc/instances/i-1/weight", `{"weight":5}]`)
	if rec.Code != http.StatusBadRequest {
		t.Fatalf("trailer ]: status = %d body %s", rec.Code, rec.Body.String())
	}
	// null body rescued by valid query parameter before fix
	rec = doRawRequest(t, router, http.MethodPut,
		"/api/v1/services/svc/instances/i-1/weight?weight=9", `null`)
	if rec.Code != http.StatusBadRequest {
		t.Fatalf("null body: status = %d body %s", rec.Code, rec.Body.String())
	}
	got, found := publicInstance(t, router, "svc", "i-1")
	if !found || got["weight"].(float64) != 10 {
		t.Fatalf("weight changed: %v", got)
	}
}
EOF
