1	package api
2	
3	import (
4		"net/http"
5		"strings"
6		"testing"
7		"time"
8	)
9	
10	func seedCleanupInstances(t *testing.T, router http.Handler) {
11		t.Helper()
12		// alpha/i-1 is strictly lost, alpha/i-2 sits exactly on the lost
13		// boundary, alpha/i-3 is unhealthy but still fresh.
14		registerInstance(t, router, map[string]any{
15			"service_name": "alpha", "instance_id": "i-1", "address": "10.0.0.1:8080",
16			"port": 8080, "healthy": true, "weight": 10, "heartbeat_at": at(0),
17		})
18		registerInstance(t, router, map[string]any{
19			"service_name": "alpha", "instance_id": "i-2", "healthy": true,
20			"weight": 5, "heartbeat_at": at(5),
21		})
22		registerInstance(t, router, map[string]any{
23			"service_name": "alpha", "instance_id": "i-3", "healthy": false,
24			"weight": 3, "heartbeat_at": at(8),
25		})
26		// beta/i-1 is strictly lost, beta/i-2 is still online.
27		registerInstance(t, router, map[string]any{
28			"service_name": "beta", "instance_id": "i-1", "healthy": true,
29			"weight": 7, "heartbeat_at": at(1),
30		})
31		registerInstance(t, router, map[string]any{
32			"service_name": "beta", "instance_id": "i-2", "healthy": true,
33			"weight": 2, "heartbeat_at": at(9),
34		})
35	}
36	
37	func cleanupRequest(t *testing.T, router http.Handler, target string, body any) (int, map[string]any) {
38		t.Helper()
39		rec := doRequest(t, router, http.MethodPost, target, body)
40		return rec.Code, decodeBody(t, rec)
41	}
42	
43	func TestCleanupRemovesStrictlyLostAcrossAllServices(t *testing.T) {
44		router, st := testRouter(t)
45		seedCleanupInstances(t, router)
46	
47		code, out := cleanupRequest(t, router,
48			"/api/v1/cleanup?evaluate_at="+at(10)+"&heartbeat_timeout=5m", nil)
49		if code != http.StatusOK {
50			t.Fatalf("status = %d, want 200, body %v", code, out)
51		}
52		if out["evaluate_at"] != at(10) {
53			t.Fatalf("evaluate_at = %v, want %s", out["evaluate_at"], at(10))
54		}
55		if out["heartbeat_timeout"] != float64(300) {
56			t.Fatalf("heartbeat_timeout = %v, want 300 seconds", out["heartbeat_timeout"])
57		}
58		if out["removed"] != float64(2) {
59			t.Fatalf("removed = %v, want 2", out["removed"])
60		}
61	
62		rawList, ok := out["instances"].([]any)
63		if !ok || len(rawList) != 2 {
64			t.Fatalf("instances = %v, want two removed records", out["instances"])
65		}
66		first := rawList[0].(map[string]any)
67		second := rawList[1].(map[string]any)
68		if first["service_name"] != "alpha" || first["instance_id"] != "i-1" ||
69			second["service_name"] != "beta" || second["instance_id"] != "i-1" {
70			t.Fatalf("removed order = %v, want alpha/i-1 then beta/i-1", rawList)
71		}
72		if first["address"] != "10.0.0.1:8080" || first["port"] != float64(8080) ||
73			first["healthy"] != true || first["weight"] != float64(10) ||
74			first["heartbeat_at"] != at(0) {
75			t.Fatalf("removed record mismatch: %v", first)
76		}
77	
78		for _, key := range [][2]string{{"alpha", "i-1"}, {"beta", "i-1"}} {
79			if _, found, err := st.GetInstance(key[0], key[1]); err != nil || found {
80				t.Fatalf("%s/%s should be deleted: found=%v err=%v", key[0], key[1], found, err)
81			}
82		}
83		// Boundary, unhealthy-but-fresh and online records all survive.
84		for _, key := range [][2]string{{"alpha", "i-2"}, {"alpha", "i-3"}, {"beta", "i-2"}} {
85			if _, found, err := st.GetInstance(key[0], key[1]); err != nil || !found {
86				t.Fatalf("%s/%s should survive: found=%v err=%v", key[0], key[1], found, err)
87			}
88		}
89	}
90	
91	func TestCleanupScopedToOneServiceLeavesOthersUntouched(t *testing.T) {
92		router, st := testRouter(t)
93		seedCleanupInstances(t, router)
94	
95		code, out := cleanupRequest(t, router, "/api/v1/cleanup", map[string]any{
96			"service_name": "alpha", "evaluate_at": at(10), "heartbeat_timeout": "5m",
97		})
98		if code != http.StatusOK {
99			t.Fatalf("status = %d, want 200, body %v", code, out)
100		}
101		if out["removed"] != float64(1) {
102			t.Fatalf("removed = %v, want 1", out["removed"])
103		}
104		if ids := instanceIDs(t, out); len(ids) != 1 || ids[0] != "i-1" {
105			t.Fatalf("removed ids = %v, want [i-1]", ids)
106		}
107		// The equally lost record of the other service must remain.
108		if _, found, err := st.GetInstance("beta", "i-1"); err != nil || !found {
109			t.Fatalf("beta/i-1 must be untouched: found=%v err=%v", found, err)
110		}
111		if _, found, err := st.GetInstance("alpha", "i-1"); err != nil || found {
112			t.Fatalf("alpha/i-1 should be deleted: found=%v err=%v", found, err)
113		}
114	}
